import { Line } from '@visx/shape';
import React, { forwardRef } from 'react';

import Colors from '@dynatrace/strato-design-tokens/colors';

import { BottomMagnifier } from './components/BottomMagnifier.js';
import { WithChildren } from '../../../../core/types/with-children.js';
import { _usePoliteContainer } from '../../../../overlays/hooks/_usePoliteContainer.js';

interface VerticalCrosshairProps {
  /** Coordinate x for crosshair */
  x: number;
  /** Label for crosshair */
  label?: string;
  /** Height for crosshair line */
  height: number;
  /** Top margin for crosshair line */
  top?: number;
  /** Vertical offset */
  offset?: number;
  /** Indicates wether the line needs to be dashed */
  dashed?: boolean;
  /** Line & magnifier color */
  color?: string;
  /** Makes the element accesible through keyboard */
  focusable?: boolean;
}

export const VerticalCrosshair = forwardRef<
  SVGLineElement,
  VerticalCrosshairProps & WithChildren
>((props: VerticalCrosshairProps, ref) => {
  const {
    x,
    label,
    height,
    top = 0,
    offset = 0,
    dashed = true,
    color = Colors.Border.Neutral.Accent,
    focusable,
  } = props;

  const Portal = _usePoliteContainer();

  const lineStrokeDasharray = dashed ? '3,2' : '0,0';
  const from = { x, y: top };
  const to = { x, y: top + height };
  const strokeWidth = 1;

  return (
    <>
      {x > 0 && (
        <Line
          data-testid="crosshair"
          innerRef={ref}
          from={from}
          to={to}
          stroke={color}
          strokeWidth={strokeWidth}
          strokeDasharray={lineStrokeDasharray}
          pointerEvents={'none'}
          tabIndex={focusable ? 0 : -1}
        />
      )}
      {label && (
        <Portal>
          <BottomMagnifier label={label} mouseX={x} offset={offset} />
        </Portal>
      )}
    </>
  );
});

VerticalCrosshair['displayName'] = 'VerticalCrosshair';
